// RuntimeContentServiceServer is the server API for RuntimeContentService service.
// All implementations must embed UnimplementedRuntimeContentServiceServer
// for forward compatibility.
//
// RuntimeContentService is elitea-main's runtime content plane (#1359 U4):
// the claim-bound data a running execution reads and writes, and the sandbox
// package/snapshot/workspace content a sandbox supervisor moves. It is served
// on Main's private content listener (ELITEA_RUNTIME_CONTENT_ADDRESS, :9445):
// gRPC only, TLS 1.3, a runtime-CA client certificate required at the
// handshake. It replaced the claim-bound HTTPS routes of that port.
//
// AUTHORIZATION. The listener's grpcauth policy admits any verified runtime
// workload identity to the service; every RPC then binds its own authority to
// that identity, exactly as the HTTPS routes did:
//
//   - Execution-bound RPCs (every request that carries a RuntimeContentScopeV1)
//     are made under a live claim. The claim id and the 32-byte fence token
//     travel as gRPC metadata, never in the message:
//     elitea-claim-id         the accepted claim's id (one value)
//     elitea-claim-fence-bin  the raw 32-byte fence token (binary metadata)
//     Main binds the claim, the fence, the generation and the verified peer
//     certificate to the durable execution state before anything is read or
//     written.
//   - Sandbox content RPCs (bundles, compiled snapshots, workspace reads) carry
//     a Main-signed sandbox grant whose audience must be the verified peer.
//
// JSON DOCUMENTS. Many requests and responses carry a JSON document as bytes
// (`*_json`). Those are the versioned runtime documents the HTTPS routes
// carried as bodies (schema names inside them, strict unknown-field refusal on
// both sides); gRPC is their transport, not their schema.
//
// STATUS CODES. One mapping replaces the HTTP statuses:
//
//	InvalidArgument     malformed request (was 400)
//	Unauthenticated     no verified peer, missing or malformed claim (401)
//	PermissionDenied    the claim, fence, grant or identity is refused (403)
//	NotFound            the named content does not exist (404)
//	Aborted             a conflict with the durable state (409)
//	ResourceExhausted   the content exceeds its limit (413)
//	FailedPrecondition  the document cannot be served or stored as written (422)
//	DeadlineExceeded    the transfer was interrupted (408)
//	Unavailable         overload or a dependency is unavailable; retry (503/502)
//	Internal            the stored content failed verification (500)
//	Unimplemented       this deployment does not serve the RPC (a route the
//	                    HTTPS listener left unregistered)
type RuntimeContentServiceServer interface {
	// One claim-bound, source-verified agent input: one header, then chunks.
	GetInput(*GetInputRequestV1, grpc.ServerStreamingServer[GetInputResponseV1]) error
	// The Elitea client-token runtime context of the claimed execution.
	GetEliteaClientToken(context.Context, *GetEliteaClientTokenRequestV1) (*GetEliteaClientTokenResponseV1, error)
	// One frozen nested (agent-as-tool) application version.
	GetApplicationVersion(context.Context, *GetApplicationVersionRequestV1) (*GetApplicationVersionResponseV1, error)
	// One stored chat attachment's text.
	GetAttachmentObject(context.Context, *GetAttachmentObjectRequestV1) (*GetAttachmentObjectResponseV1, error)
	// One claim-scoped HTTP action invocation.
	ExecuteHTTPAction(context.Context, *ExecuteHTTPActionRequestV1) (*ExecuteHTTPActionResponseV1, error)
	// The two chat-authored builder writes (#940 A8).
	WriteSkill(context.Context, *WriteSkillRequestV1) (*WriteSkillResponseV1, error)
	WriteProjectContext(context.Context, *WriteProjectContextRequestV1) (*WriteProjectContextResponseV1, error)
	// The `artifact` toolkit family (#906).
	ListArtifacts(context.Context, *ListArtifactsRequestV1) (*ListArtifactsResponseV1, error)
	ReadArtifact(context.Context, *ReadArtifactRequestV1) (*ReadArtifactResponseV1, error)
	WriteArtifact(context.Context, *WriteArtifactRequestV1) (*WriteArtifactResponseV1, error)
	DeleteArtifact(context.Context, *DeleteArtifactRequestV1) (*DeleteArtifactResponseV1, error)
	// The Code workspace manifest of the claimed execution.
	ResolveCodeWorkspace(context.Context, *ResolveCodeWorkspaceRequestV1) (*ResolveCodeWorkspaceResponseV1, error)
	// Code debug artifacts: admit a visit, then commit its snapshot.
	AdmitCodeDebug(context.Context, *AdmitCodeDebugRequestV1) (*AdmitCodeDebugResponseV1, error)
	CommitCodeDebug(context.Context, *CommitCodeDebugRequestV1) (*CommitCodeDebugResponseV1, error)
	// The Code platform pump: one step, and the read-only effects question.
	StepCodePlatform(context.Context, *StepCodePlatformRequestV1) (*StepCodePlatformResponseV1, error)
	ReadCodePlatformEffects(context.Context, *ReadCodePlatformEffectsRequestV1) (*ReadCodePlatformEffectsResponseV1, error)
	// Node recovery control, acknowledgement and recovered results.
	PollNodeRecovery(context.Context, *PollNodeRecoveryRequestV1) (*PollNodeRecoveryResponseV1, error)
	AcknowledgeNodeRecovery(context.Context, *AcknowledgeNodeRecoveryRequestV1) (*AcknowledgeNodeRecoveryResponseV1, error)
	ReadNodeRecoveryResult(context.Context, *ReadNodeRecoveryResultRequestV1) (*ReadNodeRecoveryResultResponseV1, error)
	// The per-interrupt decision ledger of the claimed execution
	// (contracts/fanout-interrupt-decisions-v1.md v1.1 §7): the decided cards
	// and the acknowledgement of one applied decision. Both payloads are the
	// contract's canonical JSON; a refusal is a status code (§7.1).
	FetchExecutionInterrupts(context.Context, *FetchExecutionInterruptsRequestV1) (*FetchExecutionInterruptsResponseV1, error)
	AcknowledgeExecutionInterrupt(context.Context, *AcknowledgeExecutionInterruptRequestV1) (*AcknowledgeExecutionInterruptResponseV1, error)
	// The original Code sandbox visit and intent registrations.
	RegisterCodeVisit(context.Context, *RegisterCodeVisitRequestV1) (*RegisterCodeVisitResponseV1, error)
	RegisterCodeIntent(context.Context, *RegisterCodeIntentRequestV1) (*RegisterCodeIntentResponseV1, error)
	// The immutable toolkit available-tools result of one admitted input.
	PutToolkitDiscoveryResult(context.Context, *PutToolkitDiscoveryResultRequestV1) (*PutToolkitDiscoveryResultResponseV1, error)
	GetToolkitDiscoveryResult(context.Context, *GetToolkitDiscoveryResultRequestV1) (*GetToolkitDiscoveryResultResponseV1, error)
	// Sandbox workspace content, under a signed workspace-read proof.
	ReadSandboxWorkspaceManifest(context.Context, *ReadSandboxWorkspaceManifestRequestV1) (*ReadSandboxWorkspaceManifestResponseV1, error)
	ReadSandboxWorkspaceFile(context.Context, *ReadSandboxWorkspaceFileRequestV1) (*ReadSandboxWorkspaceFileResponseV1, error)
	// Shared sandbox dependency bundles (Python and native), under a signed
	// sandbox grant. Metadata is published last.
	GetSandboxBundle(context.Context, *GetSandboxBundleRequestV1) (*GetSandboxBundleResponseV1, error)
	PublishSandboxBundle(context.Context, *PublishSandboxBundleRequestV1) (*PublishSandboxBundleResponseV1, error)
	// One bundle file: one header, then chunks.
	FetchSandboxBundleFile(*FetchSandboxBundleFileRequestV1, grpc.ServerStreamingServer[FetchSandboxBundleFileResponseV1]) error
	// One bundle file: one header, then chunks.
	UploadSandboxBundleFile(grpc.ClientStreamingServer[UploadSandboxBundleFileRequestV1, UploadSandboxBundleFileResponseV1]) error
	// Rust compiled snapshots, under a signed read or publish grant.
	GetCompiledSnapshot(context.Context, *GetCompiledSnapshotRequestV1) (*GetCompiledSnapshotResponseV1, error)
	PublishCompiledSnapshot(context.Context, *PublishCompiledSnapshotRequestV1) (*PublishCompiledSnapshotResponseV1, error)
	FetchCompiledSnapshotFile(*FetchCompiledSnapshotFileRequestV1, grpc.ServerStreamingServer[FetchCompiledSnapshotFileResponseV1]) error
	UploadCompiledSnapshotFile(grpc.ClientStreamingServer[UploadCompiledSnapshotFileRequestV1, UploadCompiledSnapshotFileResponseV1]) error
	mustEmbedUnimplementedRuntimeContentServiceServer()
}

